'use client';
import {FinancialUnifiedHistory} from './financial-unified-history';
import {FinancialSplitHistory} from './financial-split-history';
import {FinancialMatchCorrection} from './financial-match-correction';
import {FinancialOpeningAccount} from './financial-opening-account';
import {useEffect,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
import {downloadReport} from '@/lib/report-export';
import {openFinancialMigrationPrint} from '@/lib/financial-migration-print';
import {readFinancialMigrationDetail,financialMigrationDetailRows,financialMigrationCorrectionRows} from '@/lib/financial-migration-detail';
export function FinancialMigrationDetail({scope,batch}:{scope:HandoffScope;batch:string}){
 const [reservation,setReservation]=useState<string|null>(null);
 const [detail,setDetail]=useState<ReturnType<typeof readFinancialMigrationDetail>|null>(null),[error,setError]=useState(''),[attempt,setAttempt]=useState(0);
 useEffect(()=>{let active=true;setDetail(null);setError('');async function load(){try{const identify=async()=>{const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.')};await identify();const value=readFinancialMigrationDetail(await hotelRpc('financial_migration_detail',{p_tenant:scope.tenant,p_property:scope.property,p_batch:batch}),scope,batch);await identify();if(active)setDetail(value)}catch(e){if(active)setError(e instanceof Error?e.message:'Unable to read saved batch.')}}void load();return()=>{active=false}},[scope.tenant,scope.property,scope.actor,batch,attempt]);
 return <section className="card"><h2>Saved financial batch</h2>{error?<><p role="alert">{error}</p><button onClick={()=>setAttempt(a=>a+1)}>Retry batch details</button></>:!detail?<p role="status">Loading saved source records…</p>:<><p>{detail.sourceBatch} · {detail.provider} · {detail.cutover} · {detail.status}</p><div className="table-wrap"><table><caption>Original imported amounts and accounting references</caption><thead><tr><th>Source item</th><th>Reference</th><th>Category</th><th>Amount (USD)</th><th>Accounting references</th></tr></thead><tbody>{detail.rows.map((row,index)=><tr key={index}><td>{row.source}</td><td>{row.reference}</td><td>{row.category}</td><td>{row.amount?bankCloseMoney(row.amount):'Invalid amount'}</td><td>{detail.unified?<>See invoice and deposit portions below</>:detail.split?<>See split portions below</>:detail.links.has(row.source)?<><p>Opening: {detail.links.get(row.source)?.opening}</p><p>Journal: {detail.links.get(row.source)?.journal}</p></>:detail.invoiceMatches.has(row.source)?<><p>Matched to existing invoice: {detail.invoiceMatches.get(row.source)?.invoice}</p><p>{detail.invoiceMatches.get(row.source)?.evidence}</p><p>No new opening balance</p>{!!detail.invoiceMatches.get(row.source)?.corrections.length&&<><p>Current invoice: {detail.invoiceMatches.get(row.source)?.currentInvoice}</p><ol aria-label="Invoice match correction history">{detail.invoiceMatches.get(row.source)?.corrections.map(c=><li key={c.id}>Version {c.version}: {c.previous} to {c.invoice} — {c.reason} · {c.created} · Actor {c.actor}</li>)}</ol></>}</>:'Not posted'}</td></tr>)}</tbody></table></div>{detail.unified&&<FinancialUnifiedHistory history={detail.unified}/>}{detail.split&&<FinancialSplitHistory history={detail.split}/>}<button type="button" onClick={()=>{try{downloadReport('financial-migration-'+batch,financialMigrationDetailRows(detail))}catch(e){setError(e instanceof Error?e.message:'Unable to export batch review.')}}}>Export batch review CSV</button><button type="button" onClick={()=>{try{openFinancialMigrationPrint(detail)}catch(e){setError(e instanceof Error?e.message:'Unable to open printable batch report.')}}}>Open printable batch report</button><button type="button" onClick={()=>{try{openFinancialMigrationPrint(detail,true)}catch(e){setError(e instanceof Error?e.message:'Unable to download printable report.')}}}>Download printable report</button>{(detail.unified?detail.unified.records.some(m=>m.corrections.length>0):detail.split?detail.split.matches.some(m=>m.corrections.length>0):Array.from(detail.invoiceMatches.values()).some(m=>m.corrections.length>0))&&<button type="button" onClick={()=>{try{downloadReport('financial-migration-corrections-'+batch,financialMigrationCorrectionRows(detail))}catch(e){setError(e instanceof Error?e.message:'Unable to export correction history.')}}}>Export invoice match corrections CSV</button>}{detail.status==='committed'&&Array.from(new Set(detail.rows.map(row=>row.reservation).filter((id):id is string=>!!id))).map(id=><button type="button" key={id} onClick={()=>setReservation(id)}>View migrated account {id}</button>)}{reservation&&<FinancialOpeningAccount key={reservation} scope={scope} reservation={reservation} initialDate={detail.cutover}/>}<FinancialMatchCorrection key={[scope.tenant,scope.property,scope.actor,batch].join(':')} scope={scope} batch={batch} matches={detail.unified?detail.unified.records.filter(r=>r.kind==='invoice').map(r=>({id:r.id,reservation:r.reservation,source:r.source})):detail.split?detail.split.matches.map(m=>({id:m.id,reservation:m.reservation,source:m.source})):detail.rows.flatMap(row=>{const m=detail.invoiceMatches.get(row.source);return m&&row.reservation?[{id:m.id,reservation:row.reservation,source:row.source}]:[]})} onCompleted={()=>setAttempt(a=>a+1)}/><details><summary>Source file fingerprint</summary><code>{detail.fingerprint}</code></details></>}</section>;
}

